function renderColors(){const holder=$('#colors');holder.innerHTML=settings.colors.map((color,i)=>`<div class="color-item"><input type="color" value="${color}" data-color="${i}" aria-label="Note color ${i+1}"><button data-remove-color="${i}" title="Remove color ${i+1}" ${settings.colors.length===1?'disabled':''}>×</button></div>`).join('')+'<button id="add-color" aria-label="Add note color">＋</button>';holder.querySelectorAll<HTMLInputElement>('[data-color]').forEach(el=>el.oninput=()=>{settings.colors[Number(el.dataset.color)]=el.value;persist();updatePreview()});holder.querySelectorAll<HTMLElement>('[data-remove-color]').forEach(el=>el.onclick=()=>{if(settings.colors.length<2)return;settings.colors.splice(Number(el.dataset.removeColor),1);persist();renderColors();updatePreview()});$('#add-color').onclick=()=>{if(settings.colors.length>=128){toast('Maximum 128 colors');return}settings.colors.push('#ffffff');persist();renderColors()}}
