  const request=launches.begin(),chosenSpeed=recorded?.speed??speed,chosenMods=recorded?.mods??[...mods],start=recorded?.startFrom??startFrom;starting=true;
  const button=$<HTMLButtonElement>('#play');if(button)button.disabled=true;$<HTMLButtonElement>('#mobile-play').disabled=true;const canvas=$<HTMLCanvasElement>('#scene');
  try{
    setTouchMode(prefersTouch(lastPointerType,touchAvailable));const capture=captureMouse(),fullscreen=enterFullscreen();
    audio??=new Audio();await audio.init();if(!launches.current(request))return;const chart=await ensureDownloaded(target);if(!launches.current(request))return;await renderer.warm(settings);if(!launches.current(request))return;await audio.load(chart);if(!launches.current(request))return;await audio.ctx.resume();if(!launches.current(request))return;audio.setVolume(settings);
    selected=chart;replay=recorded;replaySettings=recorded?sanitizeSettings(recorded.settings):undefined;const gameSettings=currentSettings();attempt=new Attempt(chart,chosenSpeed,chosenMods);frame=0;paused=false;finishing=false;frames=[];lastRecord=-Infinity;replayIndex=0;cursor={x:0,y:0};spin={x:0,y:0};
    for(let i=0;i<chart.notes.length&&chart.notes[i].time<start;i++)attempt.judged[i]=3;
    renderer.begin();frameLimiter.reset();clockOrigin=audio.ctx.currentTime;timeOrigin=start-attempt.speed*1000-approachTime(gameSettings)*1000;gameTime=timeOrigin;audio.play(gameTime,attempt.speed,gameSettings.offset);
    document.body.classList.add('playing');$('#app').hidden=true;$('#results').hidden=true;$('#pause').hidden=true;$('#hud').hidden=false;$('#hud-title').textContent=chart.title;$('#hud-sub').textContent=`${recorded?'REPLAY · ':''}${chart.artist} · ${attempt.speed.toFixed(2)}× · ${attempt.mods.join(' / ')||'No mods'}`;hud(gameTime);canvas.style.cursor='none';await Promise.all([capture,fullscreen]);
    if(launches.current(request)&&attempt&&!finishing&&!touchPlaying&&!document.pointerLockElement&&!recorded&&!attempt.mods.includes('Autoplay'))toast('Click the playfield to capture your mouse.');
  }catch(error){if(launches.current(request)&&!attempt){audio?.stop();stopCapture()}throw error}finally{if(launches.current(request)){starting=false;if(button)button.disabled=false;$<HTMLButtonElement>('#mobile-play').disabled=false}}
