function hud(t:number){const a=attempt!;$('#hud-score').textContent=String(a.score).padStart(6,'0');$('#hud-accuracy').textContent=a.accuracy.toFixed(2);$('#hud-combo').textContent=String(a.combo);$('#hud-multiplier').textContent=String(a.multiplier);$('#hud-health').style.width=a.health+'%';$('#hud-progress').style.width=clamp(t/Math.max(1,a.chart.length)*100,0,100)+'%';$('#hud-time').textContent=`${duration(t)} / ${duration(a.chart.length)}`;$('#game-fps').textContent=String(renderer.fps)}
