  let saveError='';if(!replay){try{const id=crypto.randomUUID();lastReplay={id,version:1,mapId:a.chart.id,speed:a.speed,mods:a.mods,settings:structuredClone(settings),frames,results:Array.from(a.results),startFrom};await save('replays',lastReplay);const score:Score={id,mapId:a.chart.id,date:new Date().toISOString(),score:a.score,accuracy:a.accuracy,combo:a.maxCombo,hits:a.hits,misses:a.misses,speed:a.speed,mods:a.mods,alive:a.alive,replayId:id};await save('scores',score);scores.push(score)}catch{saveError='This browser could not save the score. Export your replay before leaving.'}}
