async function watchReplay(id:string){const r=(await records<WebReplay>('replays')).find(r=>r.id===id);if(!r)throw Error('Replay not found');frame=0;await startGame(r)}
function validateReplay(r:WebReplay){if(r.version!==1||!Array.isArray(r.frames)||!Array.isArray(r.results)||r.frames.length>1_000_000||r.results.length>2_000_000||!Number.isFinite(r.speed)||r.speed<0.25||r.speed>3||!Number.isFinite(r.startFrom))throw Error('Invalid web replay');let last=-Infinity;for(const f of r.frames){if(!Array.isArray(f)||f.length!==3||!f.every(Number.isFinite)||f[0]<last)throw Error('Invalid replay frames');last=f[0]}const m=maps.find(m=>m.id===r.mapId);if(!m)throw Error('Import the matching map before its replay');if(r.results.length!==m.notes.length||!r.results.every(v=>Number.isFinite(v)&&v>=-2&&v<=HIT_WINDOW))throw Error('Replay notes do not match this map');r.mods=r.mods.filter(m=>MODS.includes(m));r.settings=sanitizeSettings(r.settings);return r}
