$('#profile-input').onchange=async()=>{const input=$<HTMLInputElement>('#profile-input');try{const f=input.files?.[0];if(f){settings=sanitizeSettings(JSON.parse(await f.text()));persist();renderSettings();toast('Profile imported')}}catch(e){report(e)}input.value=''};
$('#replay-input').onchange=async()=>{const input=$<HTMLInputElement>('#replay-input');try{const f=input.files?.[0];if(f){const r=validateReplay(JSON.parse(await f.text()));frame=0;await startGame(r)}}catch(e){report(e)}input.value=''};
window.addEventListener('keydown',e=>{if(starting&&e.code==='Escape'){e.preventDefault();cancelStart();if(screen==='library')renderDetail();return}if(screen==='pause-settings'&&e.code==='Escape'){e.preventDefault();closePauseSettings();return}if((e.target as HTMLElement).matches('input,select,textarea'))return;if(attempt&&!finishing){if(e.code==='Space'||e.code==='Escape'){e.preventDefault();if(paused)void resume().catch(report);else pause()}if(e.code==='KeyR'){frame=0;void retry().catch(report)}if(e.code==='Tab'){e.preventDefault();if(!$('#skip').hidden)$('#skip').click()}}else if(e.code==='Enter'&&screen==='library'){frame=0;void startGame().catch(report)}});
function moveRelative(dx:number,dy:number){const s=currentSettings(),sensitivity=s.sensitivity*s.fov/70/120;if(cameraMode==='Spin'){spin.x=clamp(spin.x-dy*sensitivity/Math.PI,-1.5,1.5);spin.y-=dx*sensitivity/Math.PI;cursor.x=clamp(-Math.tan(spin.y)*CAMERA_Z,-CURSOR_BOUND,CURSOR_BOUND);cursor.y=clamp(Math.tan(spin.x)*CAMERA_Z,-CURSOR_BOUND,CURSOR_BOUND)}else{cursor.x=clamp(cursor.x+dx*sensitivity,-CURSOR_BOUND,CURSOR_BOUND);cursor.y=clamp(cursor.y-dy*sensitivity,-CURSOR_BOUND,CURSOR_BOUND)}}
document.addEventListener('mousemove',event=>{if(!attempt||paused||replay||touchPlaying||attempt.mods.includes('Autoplay')||!document.pointerLockElement)return;moveRelative(event.movementX,event.movementY)});
touchControls=bindTouchAim($<HTMLCanvasElement>('#scene'),{enabled:()=>!!attempt&&!paused&&!finishing&&!replay&&!attempt.mods.includes('Autoplay'),activate:()=>{setTouchMode(true);if(document.pointerLockElement)document.exitPointerLock?.()},move:point=>{const s=currentSettings();if(s.touchMode==='relative'||cameraMode==='Spin')moveRelative(point.dx,point.dy);else{const rect=$('#scene').getBoundingClientRect();cursor=screenAim(point.x,point.y,rect,gameViewport(rect.width,rect.height,s.fov).fov)}},cancel:pause});
$('#scene').onclick=()=>{if(!attempt||paused||finishing||prefersTouch(lastPointerType,touchAvailable))return;setTouchMode(false);void captureMouse()};
$('#mobile-play').onclick=()=>void startGame().catch(report);
document.addEventListener('pointerlockchange',()=>{if(!document.pointerLockElement&&attempt&&!paused&&!finishing&&!touchPlaying)pause()});window.addEventListener('orientationchange',pause);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});window.addEventListener('blur',pause);window.addEventListener('renderer-lost',()=>{pause();toast('Graphics context was lost. Reload to restart the renderer.')});
let drag=0;window.addEventListener('dragover',e=>e.preventDefault());window.addEventListener('dragenter',e=>{e.preventDefault();if(e.dataTransfer?.types.includes('Files')){drag++;$('#drop').hidden=false}});window.addEventListener('dragleave',()=>{if(--drag<=0)$('#drop').hidden=true});window.addEventListener('drop',e=>{e.preventDefault();drag=0;$('#drop').hidden=true;void importFiles([...e.dataTransfer?.files||[]]).catch(report)});
window.addEventListener('beforeunload',e=>{if(attempt&&!finishing){e.preventDefault();e.returnValue=''}});
async function init(){try{const [stored,oldScores]=await Promise.all([records<Chart>('maps'),records<Score>('scores')]);maps.push(...uploadedMaps(stored));selected=maps[0]||EMPTY_CHART;scores=oldScores;try{for(const m of uploadedMaps(JSON.parse(localStorage.getItem('chromrhythia-shared-index')||'[]')))if(!maps.some(c=>c.id===m.id))maps.push(m);if(!selected.id)selected=maps[0]||EMPTY_CHART}catch{}}catch{toast('Browser storage is unavailable. Imported maps and scores may not persist.')}navigate('library');void refreshShared(false);let lastHud=0,lastFps=0;const animate=(now=performance.now())=>{requestAnimationFrame(animate);if(document.hidden)return;const s=currentSettings();if(attempt&&!finishing){gameTime=currentTime();if(!paused)processNotes(gameTime);if(attempt&&!paused&&!finishing&&frameLimiter.ready(now,settings.frameLimit)){renderer.render(gameTime,s,attempt,cursor,false,cameraMode==='Spin'?spin:{x:0,y:0});if(now-lastHud>(renderer.compact?1000/30:100)){hud(gameTime);lastHud=now}}}else if(!attempt&&previewing&&screen==='library'&&now-lastPreviewDraw>1000/30){lastPreviewDraw=now;if(previewing&&audio){previewAt=previewOrigin+(audio.ctx.currentTime-previewClock)*1000*previewSpeed;if(previewAt>=selected.length||previewAt-previewOrigin>20000)stopPreview()}const canvas=$<HTMLCanvasElement>('#runway-preview');if(canvas&&selected.id)drawRunway(canvas,selected,previewAt||Math.max(0,(selected.notes[0]?.time||0)-200),settings,speed);if($('#preview-time'))$('#preview-time').textContent=duration(previewAt);if(previewing&&$('#preview-seek')){$<HTMLInputElement>('#preview-seek').value=String(previewAt);paintRange($<HTMLInputElement>('#preview-seek'))}}if(now-lastFps>500){$('#fps').textContent=attempt?String(renderer.fps||'—'):'—';$('#game-performance').textContent=renderer.fps?renderer.fps+' FPS':'— FPS';lastFps=now}};animate()}
void renderer.warm(settings).catch(report);
void init();
